package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.MessageManager;import com.bedlessfighter.necroManager.managers.ConfigManager;import org.bukkit.command.*;import org.jetbrains.annotations.NotNull;
public final class MotdCommand implements CommandExecutor {public boolean onCommand(@NotNull CommandSender s, @NotNull Command c, @NotNull String label, @NotNull String @NotNull [] a){if(a.length!=0){MessageManager.sendRaw(s,MessageManager.prefix()+" &cUsage: /motd");return true;}for(String line:ConfigManager.getStringList("motd",java.util.List.of("&aWelcome to the server!")))MessageManager.sendRaw(s,MessageManager.color(line));return true;}}